    for i in range(attempts):
        for char in password:
            if char not in password:
                return False
        return True

def dictionary_attack(password, dictionary):
    for word in dictionary:
        if word in password:
            return True
    return False

def simulate_password_recovery(password, attempts):
    if brute_force_attack(password, attempts):
        print("Password recovered using brute force attack")
    elif dictionary_attack(password, "dictionary.txt"):
        print("Password recovered using dictionary attack")
    else:
        print("Password not recovered")

# Example usage
password = "password123"
attempts = 10
simulate_password_recovery(password, attempts)
```

In this algorithm, the `brute_force_attack` function attempts to guess the password by trying all possible characters in the password. The `dictionary_attack` function checks if the password contains any words from a predefined dictionary.

